const assert = require("node:assert/strict");
const { spawnSync } = require("node:child_process");
const { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } = require("node:fs");
const { tmpdir } = require("node:os");
const { delimiter, join, resolve } = require("node:path");
const { test } = require("node:test");

const script = resolve(__dirname, "dependabot-triage.sh");
const head = "af2d65ef9846c62d16f0d7b41d11abc45104ee68";
const otherHead = "0123456789abcdef0123456789abcdef01234567";
const marker = sha => `Assessed at head commit \`${sha}\`.`;
const botComment = body => ({ user: { login: "cli-triage[bot]" }, body });

const fakeGH = `#!/usr/bin/env node
const assert = require("node:assert/strict");
const { execFileSync } = require("node:child_process");
const { appendFileSync, readFileSync } = require("node:fs");
const args = process.argv.slice(2);
const fixture = JSON.parse(readFileSync(process.env.TRIAGE_FIXTURE_PATH, "utf8"));
appendFileSync(process.env.TRIAGE_CALLS_PATH, JSON.stringify(args) + "\\n");
if (args[0] === "pr" && args[1] === "list") {
  assert.deepEqual(args, ["pr", "list", "--repo", "octo/hello", "--state", "open",
    "--author", "app/dependabot", "--limit", "100", "--json", "number,headRefOid,statusCheckRollup"]);
  console.log(JSON.stringify(fixture.prs));
} else if (args[0] === "api") {
  assert.deepEqual(args.slice(0, 4), ["api", "repos/octo/hello/issues/12/comments", "--paginate", "--jq"]);
  assert.equal(args.length, 5);
  process.stdout.write(execFileSync("jq", ["-r", args[4]], { input: JSON.stringify(fixture.comments) }));
} else if (args[0] === "pr" && args[1] === "view") {
  assert.deepEqual(args, ["pr", "view", "12", "--repo", "octo/hello", "--json", "files", "--jq", ".files[].path"]);
  console.log(fixture.files.join("\\n"));
} else {
  throw new Error("Unexpected gh invocation: " + JSON.stringify(args));
}
`;

test("select_worklist", async t => {
  const cases = [
    {
      name: "posted asterisk marker with a generated footer",
      comments: [botComment(`**Recommendation: Merge, Confidence: High**\n\n*${marker(head)}*\n\n> Generated by Dependabot PR Triage\n\n<!-- unrelated commit: ${otherHead} -->`)],
      assessed: true,
    },
    { name: "documented underscore marker", comments: [botComment(`_${marker(head)}_`)], assessed: true },
    { name: "marker without emphasis", comments: [botComment(marker(head))], assessed: true },
    { name: "marker with bold emphasis", comments: [botComment(`**${marker(head)}**`)], assessed: true },
    { name: "no earlier assessment" },
    { name: "new head after asterisk assessment", head: otherHead, comments: [botComment(`*${marker(head)}*`)], files: ["go.mod"] },
    { name: "new head after underscore assessment", head: otherHead, comments: [botComment(`_${marker(head)}_`)] },
    { name: "latest bot marker wins", comments: [botComment(`_${marker(otherHead)}_`), botComment(`*${marker(head)}*`)], assessed: true },
    { name: "latest bot marker is for an older head", comments: [botComment(`*${marker(head)}*`), botComment(`_${marker(otherHead)}_`)] },
    { name: "another author's forged marker", comments: [{ user: { login: "octocat" }, body: `*${marker(head)}*` }] },
    { name: "forged marker after an older bot assessment", comments: [botComment(`_${marker(otherHead)}_`), { user: { login: "octocat" }, body: `*${marker(head)}*` }] },
    { name: "another author cannot override a bot assessment", comments: [botComment(`*${marker(head)}*`), { user: { login: "octocat" }, body: `_${marker(otherHead)}_` }], assessed: true },
    { name: "arbitrary full SHA is not a marker", comments: [botComment(`Reviewed commit \`${head}\`.`)] },
    { name: "abbreviated SHA", comments: [botComment(`*${marker(head.slice(0, 7))}*`)] },
    { name: "overlong SHA", comments: [botComment(`*${marker(head + "0")}*`)] },
    { name: "non-hexadecimal SHA", comments: [botComment(`*${marker("g" + head.slice(1))}*`)] },
    { name: "uppercase SHA", comments: [botComment(`*${marker(head.toUpperCase())}*`)] },
    { name: "missing backticks", comments: [botComment(`*Assessed at head commit ${head}.*`)] },
    { name: "missing closing backtick", comments: [botComment(`*Assessed at head commit \`${head}.*`)] },
    { name: "missing period", comments: [botComment(`*Assessed at head commit \`${head}\`*`)] },
    { name: "different marker text", comments: [botComment(`*Assessed commit \`${head}\`.*`)] },
    { name: "pending check run", checks: [{ name: "build", status: "IN_PROGRESS" }], pending: true },
    { name: "pending commit status", checks: [{ context: "build", state: "PENDING" }], pending: true },
    { name: "unreadable check status", checks: null, pending: true },
    { name: "terminal failed check", checks: [{ name: "build", status: "COMPLETED", conclusion: "FAILURE" }] },
  ];

  for (const entry of cases) await t.test(entry.name, t => {
    const dir = mkdtempSync(join(tmpdir(), "dependabot-triage-"));
    t.after(() => rmSync(dir, { recursive: true, force: true }));
    const fixturePath = join(dir, "fixture.json");
    const callsPath = join(dir, "calls.jsonl");
    const worklistPath = join(dir, "worklist.json");
    const outputPath = join(dir, "output");
    const safeOutputsPath = join(dir, "safe-outputs.jsonl");
    writeFileSync(join(dir, "gh"), fakeGH, { mode: 0o755 });
    writeFileSync(fixturePath, JSON.stringify({
      prs: [{ number: 12, headRefOid: entry.head ?? head, statusCheckRollup: entry.checks === undefined ? [] : entry.checks }],
      comments: entry.comments ?? [],
      files: entry.files ?? [".github/workflows/build.yml"],
    }));

    const result = spawnSync("bash", [script, "select"], {
      cwd: dir,
      env: {
        PATH: `${dir}${delimiter}${process.env.PATH}`,
        HOME: dir,
        GH_CONFIG_DIR: join(dir, "config"),
        GITHUB_REPOSITORY: "octo/hello",
        WORKLIST_PATH: worklistPath,
        GITHUB_OUTPUT: outputPath,
        GH_AW_SAFE_OUTPUTS: safeOutputsPath,
        TRIAGE_FIXTURE_PATH: fixturePath,
        TRIAGE_CALLS_PATH: callsPath,
      },
      encoding: "utf8",
      timeout: 10000,
    });
    assert.ifError(result.error);
    assert.equal(result.status, 0, result.stderr);
    assert.equal(result.stderr, "");

    const selected = !entry.assessed && !entry.pending;
    const expected = selected ? [{ number: 12, head_sha: entry.head ?? head }] : [];
    assert.deepEqual(JSON.parse(readFileSync(worklistPath, "utf8")), expected);
    const needsGo = selected && (entry.files ?? []).some(file => file === "go.mod" || file === "go.sum");
    assert.equal(readFileSync(outputPath, "utf8"),
      `count=${expected.length}\nneeds_go=${needsGo}\nreason=${selected ? "ready" : "no_work"}\nworklist_path=${worklistPath}\n`);
    const calls = readFileSync(callsPath, "utf8").trim().split("\n").map(line => JSON.parse(line));
    assert.equal(calls.length, entry.pending ? 1 : entry.assessed ? 2 : 3);
    if (selected) {
      assert.equal(existsSync(safeOutputsPath), false);
      assert.match(result.stdout, /PR #12: needs assessment/);
    } else {
      assert.deepEqual(JSON.parse(readFileSync(safeOutputsPath, "utf8")), {
        type: "noop",
        message: "No Dependabot PRs need triage: all open PRs are already assessed at their current head commit, or their CI is still pending.",
      });
      assert.match(result.stdout, entry.pending ? /PR #12: skipped, checks still pending/ : /PR #12: already assessed/);
    }
  });
});
